12	/// Extension of [`Erc1155`] that allows token holders to destroy both their
13	/// own tokens and those that they have been approved to use.
14	#[interface_id]
15	#[public]
16	#[allow(missing_docs)]
17	pub trait IErc1155Burnable {
18	    /// The error type associated to this trait implementation.
19	    type Error: Into<alloc::vec::Vec<u8>>;
20	
21	    /// Destroys a `value` amount of token from `account`.
22	    ///
23	    /// # Arguments
24	    ///
25	    /// * `&mut self` - Write access to the contract's state.
26	    /// * `account` - Account to burn tokens from.
27	    /// * `token_id` - Token id to be burnt.
28	    /// * `value` - Amount to be burnt.
29	    ///
30	    /// # Errors
31	    ///
32	    /// * [`erc1155::Error::MissingApprovalForAll`] - If the caller is not
33	    ///   `account` address and the `account` has not been approved.
34	    /// * [`erc1155::Error::InvalidSender`] - If `from` is the
35	    ///   [`Address::ZERO`].
36	    /// * [`erc1155::Error::InsufficientBalance`] - If `value` is greater than
37	    ///   the balance of the `from` account.
38	    fn burn(
39	        &mut self,
40	        account: Address,
41	        token_id: U256,
42	        value: U256,
43	    ) -> Result<(), Self::Error>;
44	
45	    /// Destroys a batch of tokens from `account`.
46	    ///
47	    /// # Arguments
48	    ///
49	    /// * `&mut self` - Write access to the contract's state.
50	    /// * `account` - Accounts to burn tokens from.
51	    /// * `token_ids` - All token id to be burnt.
52	    /// * `values` - All amount to be burnt.
53	    ///
54	    /// # Errors
55	    ///
56	    /// * [`erc1155::Error::MissingApprovalForAll`] - If the caller is not
57	    ///   `account` address and the `account` has not been approved.
58	    /// * [`erc1155::Error::InvalidSender`] - If `from` is the
59	    ///   [`Address::ZERO`].
60	    /// * [`erc1155::Error::InvalidArrayLength`] - If length of `ids` is not
61	    ///   equal to length of `values`.
62	    /// * [`erc1155::Error::InsufficientBalance`] - If any of the `values` is
63	    ///   greater than the balance of the respective token from `tokens` of the
64	    ///   `from` account.
65	    fn burn_batch(
66	        &mut self,
67	        account: Address,
68	        token_ids: Vec<U256>,
69	        values: Vec<U256>,
70	    ) -> Result<(), Self::Error>;
71	}
