73	#[public]
74	impl IErc1155Burnable for Erc1155 {
75	    type Error = erc1155::Error;
76	
77	    fn burn(
78	        &mut self,
79	        account: Address,
80	        token_id: U256,
81	        value: U256,
82	    ) -> Result<(), erc1155::Error> {
83	        self.ensure_approved_or_owner(account)?;
84	        self._burn(account, token_id, value)
85	    }
86	
87	    fn burn_batch(
88	        &mut self,
89	        account: Address,
90	        token_ids: Vec<U256>,
91	        values: Vec<U256>,
92	    ) -> Result<(), erc1155::Error> {
93	        self.ensure_approved_or_owner(account)?;
94	        self._burn_batch(account, token_ids, values)
95	    }
96	}
