366	        if from.is_zero() {
367	            return Err(erc1155::Error::InvalidSender(
368	                erc1155::ERC1155InvalidSender { sender: from },
369	            ));
370	        }
371	        self._update_with_acceptance_check(from, to, ids, values, data)
